sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
   if (isLoading || newValue === '') {
      return;
   }

   var parts;
   var begin_date = g_form.getValue('begin_date');

   if (newValue.includes('/')){
	parts = newValue.split('/');
   }

   if (begin_date.includes('/')){
	begin_date = begin_date.split('/');
   }

   for(var i=0;i<3;i++){
		parseInt(parts[i]);
		parseInt(begin_date[i]);
   }

	var begin = new Date(begin_date[2],begin_date[1] - 1,begin_date[0]);
	var end = new Date(parts[2],parts[1] - 1,parts[0]);

	if (end < begin){
		g_form.clearValue('end_date');
		g_form.showFieldMsg('end_date','The end date must not precede the start date.', 'error');
	}
   //Type appropriate comment here, and begin script below

}
